package ge.opensoft.openservice;

import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.sql.SQLException;
import java.time.*;
import java.time.format.DateTimeParseException;
import java.util.*;

/** Native demand-to-project delivery with retained manual dates and finish-to-start work. */
final class ProjectDelivery {
    private ProjectDelivery() {}
    static String filter(String record){return "NOT EXISTS(SELECT 1 FROM os_project_origin p WHERE p.project_id="+record+" AND NOT EXISTS(SELECT 1 FROM os_record_scope s WHERE s.record_id=p.project_id AND s.parent_id=p.demand_id))";}
    static Map<String,Object> record(Store.Db db,String id)throws SQLException {
        var item=WorkTasks.record(db,"project",id);for(String field:List.of("start_on","finish_on"))if(!FieldAccess.allowed(db,Service.schema(db,"project"),field))throw new Failure(403,"Project date access required");return item;
    }
    static String date(Object input){String value=WorkJobs.text(input,10);require(value.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}"),"Use calendar dates in YYYY-MM-DD form");try{LocalDate.parse(value);}catch(DateTimeParseException invalid){throw new Failure(400,"Choose a valid calendar date");}return value;}
    static Map<String,Object> latest(Store.Db db,String task)throws SQLException {var row=db.one("SELECT revision,detail FROM os_project_schedule WHERE task_id=? ORDER BY revision DESC LIMIT 1",task);return row==null?map("revision",0,"detail",map()):row;}
    static Map<String,Object> basis(Map<String,Object> task){var result=new LinkedHashMap<String,Object>();for(String field:List.of("summary","details","group_id","required","predecessors"))result.put(field,task.get(field));return result;}
    static boolean current(Map<String,Object> task,Map<String,Object> schedule){return ((Number)schedule.get("revision")).intValue()>0 && object(object(schedule.get("detail")).get("basis")).equals(basis(task));}
    static Map<String,Object> safe(Map<String,Object> row){var copy=new LinkedHashMap<>(row);var detail=new LinkedHashMap<>(object(row.get("detail")));detail.remove("basis");copy.put("detail",detail);return copy;}
    static boolean writable(Store.Db db)throws SQLException {
        var schema=Service.schema(db,"project");if(!RecordPolicy.allows(schema,"update",db.viewerRole))return false;for(String field:List.of("start_on","finish_on")){var rule=object(TypedFields.rules(schema).getOrDefault(field,map()));if(rule.containsKey("write_roles") && !((List<?>)rule.get("write_roles")).contains(db.viewerRole))return false;}return true;
    }
    static Map<String,Object> originView(Store.Db db,Map<String,Object> demand)throws SQLException {
        var origin=db.one("SELECT project_id FROM os_project_origin WHERE demand_id=?",demand.get("sys_id"));Map<String,Object> project=map();if(origin!=null)try{project=FieldAccess.serialize(db,Service.readRecord(db,"project",origin.get("project_id").toString()));}catch(Failure hidden){ /* Preserve project access boundaries. */ }
        boolean eligible=origin==null && object(demand.get("data")).get("state").equals("approved") && DemandPlanning.writable(db) && RecordPolicy.allows(Service.schema(db,"project"),"read",db.viewerRole) && RecordPolicy.allows(Service.schema(db,"project"),"create",db.viewerRole);
        if(eligible)try{DemandPlanning.ready(db,demand);}catch(Failure unavailable){eligible=false;}return map("project",project,"can_convert",eligible);
    }
    static Map<String,Object> convert(Store.Db db,String id,Object input)throws SQLException {
        if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");var demand=DemandPlanning.record(db,id);var body=object(input);require(body.keySet().equals(Set.of("record_revision")),"Provide the reviewed demand revision only");require(body.get("record_revision") instanceof Integer n && n>=0,"Use a nonnegative demand revision");if(!object(demand.get("data")).get("state").equals("approved"))throw new Failure(409,"Approve the demand before creating its project");var assessment=DemandPlanning.ready(db,demand);RecordPolicy.require(Service.schema(db,"demand"),"update",db.viewerRole);var existing=db.one("SELECT project_id FROM os_project_origin WHERE demand_id=?",id);if(existing!=null)return FieldAccess.serialize(db,Service.readRecord(db,"project",existing.get("project_id").toString()));ProblemInvestigations.revision(body.get("record_revision"),demand.get("revision"));require(db.one("SELECT record_id FROM os_record_scope WHERE record_id=?",id)==null,"Use an unscoped demand as the project's permission parent");require(db.count("SELECT COUNT(*) FROM os_record_scope WHERE parent_id=?",id)<100,"A demand supports at most 100 scoped children");String actor=Service.account(db,db.viewerId).get("name").toString();var permitted=FieldAccess.serialize(db,demand);var project=Service.create(db,"project",map("short_description",permitted.getOrDefault("short_description","Approved demand delivery"),"description",permitted.get("description")),actor);String projectId=project.get("sys_id").toString();db.update("INSERT INTO os_project_origin(project_id,demand_id,demand_revision,assessment_revision,actor_id,created) VALUES(?,?,?,?,?,?)",projectId,id,demand.get("revision"),assessment.get("revision"),db.viewerId,now());db.update("INSERT INTO os_record_scope(record_id,parent_id,revision) VALUES(?,?,1)",projectId,id);db.update("INSERT INTO os_task_plan(parent_id,revision,close_at) VALUES(?,1,'complete')",projectId);Service.update(db,"demand",demand,map(),actor,db.viewerRole,demand.get("revision").toString());Service.audit(db,project,actor,"project.converted",map("demand_id",id,"assessment_revision",assessment.get("revision")));return FieldAccess.serialize(db,project);
    }
    static List<Map<String,Object>> tasks(Store.Db db,String project)throws SQLException {var result=new ArrayList<Map<String,Object>>();for(var row:db.all("SELECT task_id FROM os_case_task WHERE parent_id=? ORDER BY ordinal",project))result.add(WorkTasks.task(db,project,row.get("task_id").toString()));return result;}
    static Map<String,Object> page(Store.Db db,String id)throws SQLException {
        var project=record(db,id);var items=new ArrayList<Map<String,Object>>();for(var task:tasks(db,id)){var schedule=latest(db,task.get("task_id").toString());items.add(map("task",task,"schedule",safe(schedule),"current",current(task,schedule)));}var origin=db.one("SELECT * FROM os_project_origin WHERE project_id=?",id);Map<String,Object> demand=map();if(origin!=null)demand=FieldAccess.serialize(db,Service.readRecord(db,"demand",origin.get("demand_id").toString()));return map("record",FieldAccess.serialize(db,project),"tasks",items,"origin",origin,"demand",demand);
    }
    static Map<String,Object> schedulePage(Store.Db db,String id,String taskId)throws SQLException {
        var project=record(db,id);var task=WorkTasks.task(db,id,taskId);var schedule=latest(db,taskId);var history=new ArrayList<Map<String,Object>>();for(var row:db.all("SELECT revision,detail FROM os_project_schedule WHERE task_id=? ORDER BY revision DESC",taskId))history.add(safe(row));return map("record",FieldAccess.serialize(db,project),"task",task,"schedule",safe(schedule),"history",history,"current",current(task,schedule),"can_edit",object(project.get("data")).get("state").equals("planning") && task.get("state").equals("queued") && writable(db));
    }
    static void validateDates(Store.Db db,Map<String,Object> project,boolean completePlan)throws SQLException {
        var data=object(project.get("data"));String starts=date(data.get("start_on")),ends=date(data.get("finish_on"));require(starts.compareTo(ends)<=0,"Project finish must not precede its start");var tasks=tasks(db,project.get("sys_id").toString());int required=0;
        for(var task:tasks){if(task.get("state").equals("cancelled"))continue;if(((Number)task.get("required")).intValue()==1)required++;var schedule=latest(db,task.get("task_id").toString());if(!current(task,schedule)){if(completePlan)throw new Failure(409,"Every live task needs a current reviewed schedule");continue;}var detail=object(schedule.get("detail"));require(detail.get("start_on").toString().compareTo(starts)>=0 && detail.get("finish_on").toString().compareTo(ends)<=0,"Task dates must remain within the project window");
            for(Object predecessor:(List<?>)task.get("predecessors")){var before=WorkTasks.task(db,project.get("sys_id").toString(),predecessor.toString());require(!before.get("state").equals("cancelled"),"A cancelled task cannot be a project predecessor");var prior=latest(db,predecessor.toString());if(current(before,prior))require(object(prior.get("detail")).get("finish_on").toString().compareTo(detail.get("start_on").toString())<=0,"Predecessor finish must not follow successor start");}
        }
        if(completePlan && required==0)throw new Failure(409,"Plan at least one required delivery task or milestone");
    }
    static Map<String,Object> schedule(Store.Db db,String id,String taskId,Object input)throws SQLException {
        if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");var project=record(db,id);if(!writable(db))throw new Failure(403,"Project schedule write access required");var task=WorkTasks.task(db,id,taskId);if(!object(project.get("data")).get("state").equals("planning") || !task.get("state").equals("queued"))throw new Failure(409,"Schedule queued tasks while the project is in planning");var body=object(input);require(body.keySet().equals(Set.of("revision","record_revision","task_revision","start_on","finish_on","milestone")),"Provide reviewed schedule fields only");var previous=latest(db,taskId);ProblemInvestigations.revision(body.get("revision"),previous.get("revision"));ProblemInvestigations.revision(body.get("record_revision"),project.get("revision"));ProblemInvestigations.revision(body.get("task_revision"),task.get("revision"));int revision=((Number)previous.get("revision")).intValue()+1;require(revision<=100,"A task supports at most 100 retained schedules");String starts=date(body.get("start_on")),ends=date(body.get("finish_on"));require(body.get("milestone") instanceof Boolean,"Choose whether this is a milestone");require(starts.compareTo(ends)<=0,"Task finish must not precede its start");boolean milestone=(Boolean)body.get("milestone");require(!milestone || starts.equals(ends),"Milestones use the same start and finish date");String actor=Service.account(db,db.viewerId).get("name").toString();var detail=map("start_on",starts,"finish_on",ends,"milestone",milestone,"basis",basis(task),"actor",actor,"actor_id",db.viewerId,"created",now());db.update("INSERT INTO os_project_schedule(task_id,revision,detail) VALUES(?,?,?)",taskId,revision,JSON.writeValueAsString(detail));validateDates(db,project,false);Service.update(db,"project",project,map(),actor,db.viewerRole,project.get("revision").toString());Service.audit(db,project,actor,"project.scheduled",map("task_id",taskId,"schedule_revision",revision));return schedulePage(db,id,taskId);
    }
    static void taskGuard(Store.Db db,Map<String,Object> project,String operation)throws SQLException {
        if(!"project".equals(project.get("table")))return;record(db,project.get("sys_id").toString());String state=object(project.get("data")).get("state").toString();if(Set.of("configure","create","revise","waive").contains(operation)){if(!state.equals("planning"))throw new Failure(409,"Return the project to planning before changing its work");}else if(operation.equals("cancel")){if(!Set.of("planning","active").contains(state))throw new Failure(409,"Reopen the project before cancelling work");}else{if(!state.equals("active"))throw new Failure(409,"Start the project before executing work");validateDates(db,project,true);}
    }
    static void guard(Store.Db db,Map<String,Object> project)throws SQLException {
        if(!"project".equals(project.get("table")))return;PortfolioResources.guard(db,project);String state=object(project.get("data")).get("state").toString();if(state.equals("planning"))return;if(state.equals("active") || state.equals("complete"))validateDates(db,project,true);if(Set.of("complete","cancelled").contains(state)){String id=project.get("sys_id").toString();if(db.count("SELECT COUNT(*) FROM os_case_task WHERE parent_id=? AND state NOT IN ('complete','cancelled')",id)>0)throw new Failure(409,"Finish or cancel every project task before closure");}
    }
    static void insertion(Map<String,Object> item){if("project".equals(item.get("table")) && !"planning".equals(object(item.get("data")).get("state")))throw new Failure(409,"Import projects in planning, then schedule their work");}
    static void deleting(Store.Db db,String id)throws SQLException {if(db.count("SELECT COUNT(*) FROM os_project_origin WHERE demand_id=?",id)>0)throw new Failure(409,"Remove the linked delivery project before deleting its demand");}
}
